const isFolder = mimeType === 'application/vnd.google-apps.folder';
const isCandidateResume = /\.(pdf|docx)$/i.test(name) && !/(^|\b)(jd|job\s*description)(\b|$)/i.test(name);
const roleFolderId = isFolder ? source.id : parents[0];
if (!roleFolderId) {
  throw new Error('Could not resolve role folder id from Google Drive trigger payload. Include id, mimeType, name, and parents fields.');
}
return [{
  json: {
    screening_service_url: $env.SCREENING_SERVICE_URL || $env.SCREENING_API_BASE_URL || 'http://host.docker.internal:4242',
    drive_folder_id: roleFolderId,
    candidate_file_id: isCandidateResume ? source.id : undefined,
    candidate_file_name: isCandidateResume ? name : undefined,
    execute: ($env.VAPI_EXECUTE_CALLS || 'false').toLowerCase() === 'true',
    trigger_file_id: source.id,
    trigger_file_name: name,
    trigger_mime_type: mimeType
  }
}];

const source = $json.body || $json;
