const local = new Date(nowUtc.getTime() + offsetMinutes * 60000);
function atLocalHour(date, hour) {
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate(), hour, 0, 0, 0) - offsetMinutes * 60000);
}
function nextBusinessStart(date) {
  const next = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate() + 1, 9, 0, 0, 0));
  while (next.getUTCDay() === 0 || next.getUTCDay() === 6) next.setUTCDate(next.getUTCDate() + 1);
  return new Date(next.getTime() - offsetMinutes * 60000);
}
const day = local.getUTCDay();
const hour = local.getUTCHours();
let waitUntil = nowUtc;
let shouldWait = false;
if (day === 0 || day === 6) {
  const monday = new Date(Date.UTC(local.getUTCFullYear(), local.getUTCMonth(), local.getUTCDate(), 9, 0, 0, 0));
  monday.setUTCDate(monday.getUTCDate() + (day === 6 ? 2 : 1));
  waitUntil = new Date(monday.getTime() - offsetMinutes * 60000);
  shouldWait = true;
} else if (hour < 9) {
  waitUntil = atLocalHour(local, 9);
  shouldWait = true;
} else if (hour >= 18) {
  waitUntil = nextBusinessStart(local);
  shouldWait = true;
}
return [{ json: { ...$json, dialing_business_hours: 'Mon-Fri 09:00-18:00', dialing_timezone_offset_minutes: offsetMinutes, dialing_wait_until: waitUntil.toISOString(), should_wait_for_dialing_window: shouldWait, queued_for_next_dialing_window: shouldWait } }];
